parser.add_argument('-p', type=int, default=4705, help='UDP port (default: 4705)')
parser.add_argument('-msg', type=str, help='message text')
parser.add_argument('-c', type=str, help='command text; cmd.exe /c is already in the packet')
parser.add_argument('-l', type=int, default=1, help='send count (default: 1)')
parser.add_argument('-t', type=int, default=22, help='seconds between sends (default: 22)')
parser.add_argument('-e', type=str, choices=['r', 's'], help='r=reboot, s=shutdown')
